CREATE OR REPLACE FUNCTION get_appraisal_ratio(ticker VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_alpha3y NUMERIC;
    v_vol3y NUMERIC;
    v_rsquared3y NUMERIC;
    v_appraisal_ratio NUMERIC;
BEGIN
    SELECT
        (risk3y->'risk_measures_3y'->>'Alpha_3Y')::numeric,
        (risk3y->'risk_measures_3y'->>'Volatility_3Y')::numeric,
        (risk3y->'risk_measures_3y'->>'R_Squared_3Y')::numeric / 100
    INTO
        v_alpha3y,
        v_vol3y,
        v_rsquared3y
    FROM risk_metrics
    WHERE investmentref = ticker;

    IF v_vol3y IS NULL OR v_vol3y = 0 OR v_rsquared3y IS NULL OR v_rsquared3y >= 1 OR v_alpha3y IS NULL THEN
        RETURN NULL;
    END IF;

    v_appraisal_ratio := v_alpha3y / (v_vol3y * POWER(1 - v_rsquared3y, 0.5));
    RETURN v_appraisal_ratio;
END;
$$ LANGUAGE plpgsql;

